mapper.update:
UPDATE diaries
SET deleted = 1, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, user_id, title, content, mood, type, voice, voice_duration,
       video, video_thumb, diary_date, created_at, updated_at, deleted
FROM diaries
WHERE user_id = #{userId}
  AND YEAR(diary_date) = #{year}
  AND MONTH(diary_date) = #{month}
  AND deleted = 0
ORDER BY diary_date DESC, created_at DESC

SELECT DISTINCT d.id, d.user_id, d.title, d.content, d.mood, d.type,
       d.voice, d.voice_duration, d.video, d.video_thumb, d.diary_date,
       d.created_at, d.updated_at, d.deleted
FROM diaries d

    d.user_id = #{userId} AND d.deleted = 0

        AND (d.title LIKE CONCAT('%', #{keyword}, '%')
             OR d.content LIKE CONCAT('%', #{keyword}, '%'))


        AND d.type = #{type}


        AND d.mood = #{mood}


        AND d.id IN (
            SELECT dt.diary_id FROM diary_tags dt
            JOIN tags t ON dt.tag_id = t.id
            WHERE t.name = #{tag} AND t.user_id = #{userId}
        )


        AND d.diary_date >= #{startDate}


        AND d.diary_date <= #{endDate}


ORDER BY d.diary_date DESC, d.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT d.id)
FROM diaries d

    d.user_id = #{userId} AND d.deleted = 0

        AND (d.title LIKE CONCAT('%', #{keyword}, '%')
             OR d.content LIKE CONCAT('%', #{keyword}, '%'))


        AND d.type = #{type}


        AND d.mood = #{mood}


        AND d.id IN (
            SELECT dt.diary_id FROM diary_tags dt
            JOIN tags t ON dt.tag_id = t.id
            WHERE t.name = #{tag} AND t.user_id = #{userId}
        )


        AND d.diary_date >= #{startDate}


        AND d.diary_date <= #{endDate}

SELECT COUNT(*)
FROM diaries
WHERE user_id = #{userId}
  AND YEAR(diary_date) = #{year}
  AND MONTH(diary_date) = #{month}
  AND deleted = 0

SELECT DISTINCT d.id, d.user_id, d.title, d.content, d.mood, d.type,
       d.voice, d.voice_duration, d.video, d.video_thumb, d.diary_date,
       d.created_at, d.updated_at, d.deleted
FROM diaries d
JOIN diary_tags dt ON d.id = dt.diary_id
JOIN tags t ON dt.tag_id = t.id
WHERE d.user_id = #{userId}
  AND d.deleted = 0
  AND t.name = #{tagName}
  AND t.user_id = #{userId}
ORDER BY d.diary_date DESC, d.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT d.id)
FROM diaries d
JOIN diary_tags dt ON d.id = dt.diary_id
JOIN tags t ON dt.tag_id = t.id
WHERE d.user_id = #{userId}
  AND d.deleted = 0
  AND t.name = #{tagName}
  AND t.user_id = #{userId}
